/**
 * MonkeyCode's sign-in: a browser window, and the HttpOnly session cookie behind it.
 *
 * WHY THE COOKIE AND NOT A KEY
 *
 * Two credentials exist on this platform — `sk-…` from the API-keys page, and `oma_…` +
 * `signing_secret` from the OhMyAgent page — and both are generated BY HAND in the console.
 * Neither has an OAuth page or a refresh endpoint, so there is no flow to automate; a key alone is
 * a snapshot that expires with nothing to renew it against.
 *
 * The session cookie is different: it is what mints the gateway key and what reads the balance, so
 * one sign-in produces a complete account. And it is HttpOnly — the reference notes say the user
 * "cannot see it in the browser at all" — which is exactly why asking for it was the wrong door.
 * `Network.getCookies` reads it, because that is the browser answering what it would send.
 *
 * @module dsh-xdpool/monkeycode-browser
 */
import { closeLoginBrowser, launchLoginBrowser, waitForCookies, type BrowserSession } from './browser-login.ts'
import { safeDecode } from './marvis-session.ts'
import type { MonkeycodeSite } from './monkeycode-protocol.ts'

/** The cookie that authenticates a session. */
export const MONKEYCODE_SESSION_COOKIE = 'monkeycode_ai_session'

/** What one browser sign-in produced. */
export interface MonkeycodeBrowserResult {
  /** The `Cookie` header value, ready to store. */
  cookie: string
  /**
   * The name the platform shows for this account, when it leaves one in the jar.
   *
   * Read from the same cookie set the session came from — the platform keeps the display name
   * among its non-HttpOnly cookies. Absent when the build does not publish one; the card then
   * falls back to the account id.
   */
  nickname?: string
}

/**
 * Open the platform and wait for a session cookie.
 *
 * The whole jar is kept rather than just the session: the platform sets more than one cookie and
 * a request that carries only the session is sometimes refused, so the header is assembled from
 * everything the browser holds for that host.
 */
export async function monkeycodeBrowserSignIn(input: {
  site: MonkeycodeSite
  timeoutMs?: number
}): Promise<MonkeycodeBrowserResult | undefined> {
  let session: BrowserSession | undefined
  try {
    session = await launchLoginBrowser(input.site.platformBaseUrl, input.site.id)
    const cookies = await waitForCookies({
      session,
      url: input.site.platformBaseUrl,
      names: [MONKEYCODE_SESSION_COOKIE],
      timeoutMs: input.timeoutMs ?? 300_000,
    })
    if (cookies === undefined) return undefined
    const header = cookies
      .filter(cookie => cookie.value !== '')
      .map(cookie => `${cookie.name}=${cookie.value}`)
      .join('; ')
    if (header === '') return undefined
    const named = cookies.find(cookie => /^(?:nick_?name|user_?name|display_?name)$/iu.test(cookie.name))
    const nickname = named === undefined ? '' : safeDecode(named.value).trim()
    return {
      cookie: header,
      ...(nickname === '' ? {} : { nickname }),
    }
  } finally {
    await closeLoginBrowser(session)
  }
}
